input.sparql:
SELECT ?zone ?point ?label ?ts WHERE {
  ?zone brick:hasPoint ?point .
  OPTIONAL { ?point rdfs:label ?label }
  ?point ref:hasTimeseriesId ?ts .
  FILTER(str(?zone) = "Perimeter_bot_ZN_2" || strcontains(str(?zone), "Perimeter_bot_ZN_2"))
  FILTER(str(?point) != "http://...")
}

SELECT ?zone ?point ?ts WHERE {
  ?zone a brick:Room .
  FILTER(strcontains(str(?zone), "Perimeter_bot"))
  ?point ref:hasTimeseriesId ?ts .
  ?point ref:hasExternalReference ?zone .
}

